import test from 'node:test';
import assert from 'node:assert/strict';
import {gunzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import {mkdtemp,readFile,writeFile,rm} from 'node:fs/promises';
import {join} from 'node:path';
import {tmpdir} from 'node:os';
import {verifyCapturedTransportArtifacts} from '../../scripts/event-captured-transport-readback.mjs';
import {inspectCapturedTransportBytes,isCapturedTransportClock} from '../../scripts/event-captured-transport.mjs';
import {transportWireFromProjection} from '../../scripts/event-marker-transport-wire.mjs';
import {parseMarkerMetadata} from '../../scripts/event-marker-metadata.mjs';
const sha=x=>createHash('sha256').update(x).digest('hex');
// Actual six-second gray/silent capture in image config e95c215c, not a fabricated transport.
const original=JSON.parse(gunzipSync(Buffer.from('','base64')));
async function fixture(fn){const directory=await mkdtemp(join(tmpdir(),'transport-readback-'));try{
 const buffers=Object.fromEntries(Object.entries(original).map(([k,v])=>[k,Buffer.from(v,'base64')]));for(const [name,data]of Object.entries(buffers))await writeFile(join(directory,name),data);
 const facts=inspectCapturedTransportBytes(buffers['captured-client.rtmp'],buffers['captured-server.rtmp'],buffers['twitch.ts'],{fps:30});
 const audioRows=parseMarkerMetadata(buffers['captured-decode-6.bin'].toString(),'audio'),videoRows=parseMarkerMetadata(buffers['captured-decode-5.bin'].toString(),'video');
 const reference=name=>({file:name,bytes:buffers[name].length,sha256:sha(buffers[name])});
 const projection={...facts,audioRows,videoRows,audioRowsSha256:sha(JSON.stringify(audioRows)),videoRowsSha256:sha(JSON.stringify(videoRows)),audioSha256:sha(buffers['captured-decode-4.bin']),videoSha256:sha(buffers['captured-decode-3.bin']),evidence:reference('captured-transport-proof.json'),decoderEvidence:reference('captured-decode-proof.json')};
 const wire=transportWireFromProjection(projection),artifacts=Object.entries(buffers).map(([name,data])=>({name,bytes:data.length,sha256:sha(data),complete:true}));return await fn({directory,wire,artifacts,buffers,projection});
 }finally{await rm(directory,{recursive:true,force:true});}}
test('complete real retained segment joins offline without issuing certificate',()=>fixture(async({directory,wire,artifacts})=>{const result=await verifyCapturedTransportArtifacts({directory,wire,artifacts});assert.equal(result.verified,true);assert.equal(result.manifestBound,true);assert.equal(isCapturedTransportClock(result),false);assert.equal(result.frames,180);}));
test('narrowed domain with freshly recomputed public checksum still rejects',()=>fixture(async({directory,projection,artifacts})=>{const changed=structuredClone(projection);changed.domain.audio[1]=changed.domain.audio[0];const wire=transportWireFromProjection(changed);await assert.rejects(verifyCapturedTransportArtifacts({directory,wire,artifacts}),/domain/);}));

test('explicit receipt table is mandatory when supplied and binds even empty stderr',()=>fixture(async({directory,wire,artifacts})=>{await assert.rejects(verifyCapturedTransportArtifacts({directory,wire,artifacts:[]}),/manifest_binding/);const rows=structuredClone(artifacts);rows.find(x=>x.name==='captured-decode.stderr').sha256='0'.repeat(64);await assert.rejects(verifyCapturedTransportArtifacts({directory,wire,artifacts:rows}),/manifest_binding/);}));
test('diagnostic mode without receipt table is explicitly unbound',()=>fixture(async({directory,wire})=>{const r=await verifyCapturedTransportArtifacts({directory,wire});assert.equal(r.manifestBound,false);assert.equal(r.scope,'offline-transport-artifact-join');}));
test('crossed proof reference with valid public checksum rejects',()=>fixture(async({directory,projection,artifacts})=>{const p=structuredClone(projection);p.evidence.sha256=p.decoderEvidence.sha256;const wire=transportWireFromProjection(p);await assert.rejects(verifyCapturedTransportArtifacts({directory,wire,artifacts}),/reference_binding/);}));
test('mutated PCM or metadata rejects original complete artifact manifest',()=>fixture(async({directory,wire,artifacts})=>{for(const name of ['captured-decode-4.bin','captured-decode-6.bin']){const path=join(directory,name),original=await readFile(path),changed=Buffer.from(original);changed[0]^=1;await writeFile(path,changed);await assert.rejects(verifyCapturedTransportArtifacts({directory,wire,artifacts}),/manifest_binding/);await writeFile(path,original);}}));
async function rewriteProof(ctx,name,change){const bytes=JSON.parse(ctx.buffers[name].toString());change(bytes);const raw=Buffer.from(JSON.stringify(bytes,null,2)+'\n');await writeFile(join(ctx.directory,name),raw);const ref={file:name,bytes:raw.length,sha256:sha(raw)},entry=ctx.artifacts.find(x=>x.name===name);Object.assign(entry,{bytes:ref.bytes,sha256:ref.sha256});const p=structuredClone(ctx.projection);p[name==='captured-transport-proof.json'?'evidence':'decoderEvidence']=ref;return transportWireFromProjection(p);}
test('decoder recipe alteration cannot be hidden by recomputed public proof/checksum',()=>fixture(async ctx=>{const wire=await rewriteProof(ctx,'captured-decode-proof.json',p=>{p.argv.push('-shortest');});await assert.rejects(verifyCapturedTransportArtifacts({...ctx,wire}),/decoder_recipe/);}));
test('native failure, missing EOF and crossed recording proof reject with fresh checksums',async()=>{for(const mode of ['exit','eof','recording'])await fixture(async ctx=>{const wire=await rewriteProof(ctx,mode==='recording'?'captured-transport-proof.json':'captured-decode-proof.json',p=>{if(mode==='exit')p.native.exitCode=1;else if(mode==='eof')p.channels[4].eof=false;else p.bindings.recording.file='/tmp/other/twitch.ts';});await assert.rejects(verifyCapturedTransportArtifacts({...ctx,wire}),/decoder_closure|decoder_channel_binding|capture_binding/);});});
test('raw row mapping alteration with recomputed wire hashes rejects decoded originals',()=>fixture(async ctx=>{const p=structuredClone(ctx.projection);p.audioRows[1].pts++;p.audioRowsSha256=sha(JSON.stringify(p.audioRows));const wire=transportWireFromProjection(p);await assert.rejects(verifyCapturedTransportArtifacts({...ctx,wire}),/row_mapping/);}));
test('physical reference equality is independent of JSON property insertion order',()=>fixture(async ctx=>{for(const name of ['evidence','decoderEvidence']){const r=ctx.wire[name];ctx.wire[name]={file:r.file,sha256:r.sha256,bytes:r.bytes};}assert.equal((await verifyCapturedTransportArtifacts(ctx)).verified,true);}));
